if(app.arguments().size()>5&&!app.arguments().last().startsWith("--")){const auto raw=app.arguments().last();p.openRaw(QUrl::fromLocalFile(raw));idle(p);check(p.frame()->metadata.input_kind=="raw","real RAW decoder");p.chooseMaterial("harman_phoenix_200_exp_v1");idle(p);check(p.frame()->source_width()>3000&&p.frame()->width()<=3400,"RAW preview/original dimensions");const auto dest=out+"/real-raw-full.tif";p.exportImage(QUrl::fromLocalFile(dest),0,95,0);idle(p);spkhost::Probe probe;std::string error;check(spkhost::probe_file(std::filesystem::path(dest.toStdWString()),probe,error),error.c_str());check(probe.width==p.frame()->source_width()&&probe.height==p.frame()->source_height(),"RAW original resolution export");}
